if __name__ == "__main__":
    KEYS = {
        "name", "synonyms", "category", "section", "base_unit", "g_per_piece", "density_g_per_ml", "shelf_life_days",
        "opened_shelf_life_days", "freezer_days", "storage", "allergens", "animal", "kcal", "protein_g", "carbs_g",
        "fat_g", "price_cents", "pack_qty", "is_staple",
    }
    seen: dict[str, str] = {}
    for e in SEED:
        n = e.get("name", "?")
        assert set(e) == KEYS, (n, sorted(set(e) ^ KEYS))
        assert e["category"] in FOOD_CATEGORIES, (n, e["category"])
        assert e["section"] in SHOP_SECTIONS, (n, e["section"])
        assert e["storage"] in ("fridge", "freezer", "pantry"), (n, e["storage"])
        assert e["base_unit"] in ("g", "ml", "pc"), (n, e["base_unit"])
        assert e["animal"] in (None, "meat", "fish", "dairy", "egg", "honey"), (n, e["animal"])
        assert isinstance(e["allergens"], list) and len(set(e["allergens"])) == len(e["allergens"]), n
        assert all(a in ALLERGENS for a in e["allergens"]), (n, e["allergens"])
        assert "lactose" not in e["allergens"] or "milk" in e["allergens"], n
        assert e["animal"] != "dairy" or "milk" in e["allergens"], n
        assert e["animal"] != "egg" or "eggs" in e["allergens"], n
        assert e["animal"] != "fish" or {"fish", "crustaceans", "molluscs"} & set(e["allergens"]), n
        if e["base_unit"] == "ml":
            assert isinstance(e["density_g_per_ml"], (int, float)) and 0.5 < e["density_g_per_ml"] < 2, n
        else:
            assert e["density_g_per_ml"] is None, n
        if e["base_unit"] == "pc":
            assert e["g_per_piece"], n
        assert e["g_per_piece"] is None or e["g_per_piece"] > 0, n
        assert isinstance(e["shelf_life_days"], int) and e["shelf_life_days"] > 0, n
        assert isinstance(e["opened_shelf_life_days"], int) and 0 < e["opened_shelf_life_days"] <= e["shelf_life_days"], n
        assert e["freezer_days"] is None or (isinstance(e["freezer_days"], int) and e["freezer_days"] > 0), n
        assert e["storage"] != "freezer" or e["freezer_days"], n
        assert isinstance(e["price_cents"], int) and e["price_cents"] > 0, n
        assert e["pack_qty"] is None or e["pack_qty"] > 0, n
        assert isinstance(e["is_staple"], bool), n
        for k in ("kcal", "protein_g", "carbs_g", "fat_g"):
            assert isinstance(e[k], (int, float)) and e[k] >= 0, (n, k)
        assert e["protein_g"] + e["carbs_g"] + e["fat_g"] <= 100.5, n
        assert isinstance(e["synonyms"], list), n
        for label in [e["name"], *e["synonyms"]]:
            assert isinstance(label, str) and label.strip() == label and label, (n, label)
            # same folding as the lookup: case, hyphens and punctuation are ignored
            key = " ".join("".join(c if c.isalnum() or c in " '" else " " for c in label.casefold().replace("-", "")).split())
            assert key not in seen, f"duplicate label {label!r}: {seen.get(key)!r} vs {n!r}"
            seen[key] = n
        # Energy plausibility (Atwater; fibre/alcohol/acids explain small gaps) - warn only.
        est = 4 * e["protein_g"] + 4 * e["carbs_g"] + 9 * e["fat_g"]
        if e["kcal"] > 40 and abs(est - e["kcal"]) > max(25, 0.25 * e["kcal"]):
            print(f"note: {n}: kcal {e['kcal']} vs macro estimate {est:.0f}")
    print(f"OK: {len(SEED)} entries, {len(seen)} unique labels")
